// C program for the function called isListSorted
// Contains target function implementation and dependency signatures

#include <assert.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

struct Node
{
    int data;
    struct Node *next;
};

// Target function implementation
int isListSorted(struct Node *list)
{
    if (list == NULL || list->next == NULL)
    {
        return 1;  /* empty or single element is sorted */
    }
    struct Node *current = list;
    while (current->next != NULL)
    {
        if (current->data > current->next->data)
        {
            return 0;  /* not sorted */
        }
        current = current->next;
    }
    return 1;  /* sorted */
}

